import { test, expect } from '@playwright/test';

const TINY_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64'
);

test.describe('图文文字社区核心流程（初版）', () => {
  test('健康检查与首页加载', async ({ page, request }) => {
    const health = await request.get('/api/health');
    expect(health.status()).toBe(200);
    const healthJson = await health.json();
    expect(healthJson.ok).toBe(true);

    await page.goto('/');
    await expect(page.locator('body')).toBeVisible();
  });

  test('邮箱验证码登录与图文发布闭环', async ({ page, request }) => {
    const uniqueEmail = `user-${Date.now()}@example.com`;
    const postTitle = `今日图文分享-${Date.now()}`;

    await page.goto('/');
    const loginBtn = page.getByRole('button', { name: /登录|邮箱登录|立即登录/i }).first();
    await expect(loginBtn).toBeVisible({ timeout: 10000 });
    await loginBtn.click();

    const emailInput = page.getByPlaceholder(/邮箱|email/i).or(page.locator('input[type="email"]')).first();
    await expect(emailInput).toBeVisible();
    await emailInput.fill(uniqueEmail);

    const sendCodePromise = page.waitForResponse((res) => res.url().includes('/api/auth/send-code') && res.request().method() === 'POST');
    const sendCodeBtn = page.getByRole('button', { name: /发送验证码|获取验证码/i }).first();
    await sendCodeBtn.click();
    const sendRes = await sendCodePromise;
    expect(sendRes.status()).toBe(200);
    const sendJson = await sendRes.json();
    expect(sendJson.devCode).toMatch(/^\d{6}$/);

    const codeInput = page.getByPlaceholder(/验证码|code/i).first();
    await codeInput.fill(sendJson.devCode);
    const submitLoginBtn = page.getByRole('button', { name: /验证并登录|确认登录|登录/i }).last();
    await submitLoginBtn.click();

    await expect(page.getByRole('button', { name: /发布图文|发布|写图文/i }).first()).toBeVisible({ timeout: 10000 });

    const uploadRes = await page.request.post('/api/uploads', {
      multipart: {
        file: { name: 'cover.png', mimeType: 'image/png', buffer: TINY_PNG },
      },
    });
    expect(uploadRes.status()).toBe(201);
    const uploadJson = await uploadRes.json();
    expect(uploadJson.url).toContain('/api/uploads/');

    const createRes = await page.request.post('/api/posts', {
      data: {
        title: postTitle,
        content: '这是一篇首版图文社区测试帖子内容。',
        imageUrl: uploadJson.url,
        tags: ['日常'],
      },
    });
    expect(createRes.status()).toBe(201);

    await page.reload();
    await expect(page.getByText(postTitle).first()).toBeVisible({ timeout: 10000 });
  });

  test('隐藏路由 /admin 登录与 Resend 配置保存', async ({ page }) => {
    await page.goto('/admin');
    const pwdInput = page.locator('input[type="password"]').first();
    await expect(pwdInput).toBeVisible({ timeout: 10000 });
    await pwdInput.fill('admin');
    await page.getByRole('button', { name: /登录|进入后台/i }).first().click();

    const keyInput = page.getByPlaceholder(/re_|Resend|API Key/i).first();
    await expect(keyInput).toBeVisible({ timeout: 10000 });
    await keyInput.fill('re_draft_test_key_12345');
    await page.getByRole('button', { name: /保存配置|保存/i }).first().click();
  });
});
